INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c74fe1ea-5edf-4e59-977a-87e42dd67e91','9','geografie-fizica','published',0,21,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c74fe1ea-5edf-4e59-977a-87e42dd67e91','ro','De ce spunem că Soarele „domină” Sistemul Solar, deși este doar o stea de mărime medie?','["Pentru că reprezintă circa 99% din masa Sistemului Solar, iar gravitația lui ține toate corpurile pe orbită.","Pentru că este cea mai mare stea din Calea Lactee.","Pentru că este singurul corp care emite lumină.","Pentru că este cel mai apropiat corp de Pământ."]','Gândește-te de unde vine forța care ține planetele legate de Soare. Soarele concentrează circa 99% din masa Sistemului Solar, așa că gravitația lui guvernează mișcarea tuturor celorlalte corpuri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('560c5af0-7470-4abb-842f-80880c94127f','9','geografie-fizica','published',1,22,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('560c5af0-7470-4abb-842f-80880c94127f','ro','În nucleul Soarelui, hidrogenul se transformă în heliu eliberând energie. Ce proces stă la baza acestei transformări?','["Fisiunea nucleară","Fuziunea nucleară","Combustia (arderea)","Evaporarea"]','Amintește-ți cum produc energie stelele, nu centralele nucleare. Energia Soarelui provine din fuziunea nucleară, în care nucleele de hidrogen se unesc și formează heliu.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b55897c1-e4f4-4398-a13f-4f3621c205d8','9','geografie-fizica','published',1,23,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b55897c1-e4f4-4398-a13f-4f3621c205d8','ro','Petele solare apar în fotosferă și sunt mai reci (circa 4500 °K) decât regiunile din jur (circa 5500 °K). De ce ni se par mai întunecate?','["Pentru că sunt găuri prin care vedem interiorul Soarelui.","Pentru că, fiind mai reci, emit mai puțină lumină decât regiunile vecine, mai fierbinți.","Pentru că reprezintă umbra planetelor pe Soare.","Pentru că sunt nori de praf cosmic."]','Leagă temperatura unei zone de cantitatea de lumină pe care o emite. O regiune mai rece strălucește mai slab, așa că petele solare apar întunecate pe fondul fotosferei mai fierbinți.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('bd770bcf-ab17-420a-bc91-211bff9420ee','9','geografie-fizica','published',1,24,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('bd770bcf-ab17-420a-bc91-211bff9420ee','ro','Coroana solară este uriașă și foarte fierbinte, dar greu de observat de pe Pământ. Când devine totuși vizibilă?','["La răsăritul și la apusul Soarelui.","În timpul unei eclipse totale de Soare, când Luna acoperă discul solar.","Pe timp de noapte, când cerul este senin.","În timpul unei eclipse de Lună."]','Coroana este ascunsă de strălucirea discului solar — ce eveniment acoperă tocmai acel disc? La o eclipsă totală de Soare, Luna acoperă discul strălucitor și coroana devine vizibilă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('85b09a92-238c-4682-aead-4b9ef106c94d','9','geografie-fizica','published',0,25,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('85b09a92-238c-4682-aead-4b9ef106c94d','ro','Numărul petelor solare crește și scade periodic, la circa 11 ani. Ce putem estima pe baza acestei regularități?','["Momentele aproximative ale maximelor de activitate solară (de exemplu, în jurul anului 2024).","Ziua exactă a următoarei eclipse de Soare.","Vârsta exactă a Soarelui.","Momentul în care Soarele se va stinge."]','O periodicitate înseamnă că fenomenul se repetă la intervale regulate, deci poate fi anticipat. Ciclul de circa 11 ani ne ajută să estimăm când va urma un nou maxim de activitate solară.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9d6bfbe0-4599-4c64-834b-c4900555e6b9','9','geografie-fizica','published',1,26,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9d6bfbe0-4599-4c64-834b-c4900555e6b9','ro','Care este ordinea corectă a etapelor în formarea Sistemului Solar?','["Protostea → nebuloasă → planete → disc protoplanetar","Nebuloasă → protostea → disc protoplanetar → planetoizi → planete","Planete → asteroizi → protostea → nebuloasă","Disc protoplanetar → planete → nebuloasă → protostea"]','Pornește de la materia difuză (un nor de gaz și praf) și mergi spre corpurile bine conturate. Ordinea este: nebuloasă → protostea → disc protoplanetar → planetoizi → planete.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('d03d8164-9f9c-417f-ba78-676c3e975e46','9','geografie-fizica','published',0,27,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('d03d8164-9f9c-417f-ba78-676c3e975e46','ro','De ce sunt grupate Mercur, Venus, Terra și Marte separat de Jupiter, Saturn, Uranus și Neptun?','["Pentru că primele sunt mici, solide și dense (telurice), iar celelalte sunt uriașe și gazoase.","Pentru că primele au sateliți, iar celelalte nu au.","Pentru că primele sunt mult mai calde decât celelalte.","Pentru că primele nu se rotesc în jurul axei."]','Compară mărimea și alcătuirea (solid sau gazos) a celor două grupe. Planetele telurice sunt mici, solide și dense, iar giganții gazoși sunt uriași și fără suprafață solidă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6eb75a97-1c42-4d72-aa10-63c31c4f53eb','9','geografie-fizica','published',1,28,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6eb75a97-1c42-4d72-aa10-63c31c4f53eb','ro','Asteroizii sunt numiți „blocuri de construcție” rămase din formarea planetelor. Ce sugerează această denumire?','["Că sunt planete întregi care s-au spart în bucăți.","Că sunt resturi de materie care nu s-au unit niciodată într-o planetă.","Că au fost construiți artificial.","Că se vor transforma cândva în stele."]','„Rămase din formare” arată că este vorba de materie care nu a apucat să formeze ceva mai mare. Asteroizii sunt resturi din discul inițial, care nu s-au adunat într-o planetă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b67aec18-6441-4c6b-8a4e-55230f792d7f','9','geografie-fizica','published',1,29,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b67aec18-6441-4c6b-8a4e-55230f792d7f','ro','Ceres, cel mai mare corp din centura de asteroizi, este clasificat ca planetă pitică, nu ca asteroid obișnuit. Ce îl deosebește, cel mai probabil?','["Faptul că are o formă neregulată.","Dimensiunea lui mult mai mare și forma aproape sferică.","Faptul că este alcătuit numai din gheață.","Faptul că orbitează Soarele."]','Gândește-te ce înseamnă că este „cel mai mare” din centură. Datorită dimensiunii mari, gravitația proprie i-a dat o formă aproape sferică, motiv pentru care e considerat planetă pitică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('88d019f4-6ea8-4ff1-a412-c67c705ef192','9','geografie-fizica','published',1,30,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('88d019f4-6ea8-4ff1-a412-c67c705ef192','ro','Vedem uneori „stele căzătoare” pe cerul nopții, deși acestea nu sunt stele. Ce sunt, de fapt?','["Stele care își sfârșesc viața și cad spre Pământ.","Meteoriți care se dezintegrează în atmosferă, lăsând dâre luminoase.","Sateliți artificiali care reflectă lumina Lunii.","Comete care lovesc Pământul."]','Leagă fenomenul luminos de frecarea cu atmosfera la intrarea unui corp ceresc. „Stelele căzătoare” sunt meteoriți care se aprind și se dezintegrează când străbat atmosfera terestră.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('25e2b32b-9ecf-423d-b88f-0c2e95e1a309','9','geografie-fizica','published',1,31,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('25e2b32b-9ecf-423d-b88f-0c2e95e1a309','ro','Centura Kuiper și planete pitice precum Pluto se află în zona Sistemului Solar de dincolo de Neptun. Ce concluzie tragem despre Pluto?','["Că Pluto este o stea mică.","Că Pluto orbitează la marginea Sistemului Solar, departe de Soare.","Că Pluto este cea mai mare planetă.","Că Pluto se află între Terra și Marte."]','Poziția „la marginea” Sistemului Solar spune ceva despre distanța față de Soare. Pluto orbitează dincolo de planetele principale, în zona rece și îndepărtată a centurii Kuiper.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('39ba01fb-7e0d-49c0-bf1d-76d88316d8e7','9','geografie-fizica','published',1,32,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('39ba01fb-7e0d-49c0-bf1d-76d88316d8e7','ro','Coada unei comete este orientată mereu dinspre Soare, indiferent de direcția în care se mișcă cometa. Care este explicația cea mai bună?','["Coada arată mereu spre direcția în care se deplasează cometa.","Coada este împinsă de Soare (vânt solar și radiație), deci este orientată dinspre el.","Coada se îndreaptă mereu spre Pământ.","Cometele nu au, de fapt, coadă."]','Întreabă-te ce „suflă” materia cometei și din ce parte vine acel impuls. Vântul solar și radiația Soarelui împing gazul și praful, așa că coada se orientează mereu în sens opus Soarelui.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('99f97e8d-ee0d-45bb-b638-44e93dfe9988','9','geografie-fizica','published',1,33,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('99f97e8d-ee0d-45bb-b638-44e93dfe9988','ro','Venus este mai departe de Soare decât Mercur, totuși este cea mai fierbinte planetă. Cum se explică acest paradox?','["Pentru că, de fapt, este mai aproape de Soare decât Mercur.","Pentru că atmosfera ei groasă de CO₂ reține căldura (efect de seră puternic).","Pentru că are foarte mulți vulcani activi.","Pentru că este cea mai mare planetă din sistem."]','Gândește-te la rolul atmosferei, nu la distanța față de Soare. Atmosfera densă de dioxid de carbon a lui Venus captează căldura printr-un efect de seră intens, ridicând temperatura peste cea de pe Mercur.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('44bce14a-432a-49c1-bc15-339cc11d892a','9','geografie-fizica','published',0,34,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('44bce14a-432a-49c1-bc15-339cc11d892a','ro','Pe Mercur temperatura variază extrem, de la circa −180 °C noaptea la circa +430 °C ziua. Ce explică cel mai bine aceste diferențe uriașe?','["Lipsa unei atmosfere care să rețină și să distribuie căldura.","Prezența unei atmosfere foarte groase, ca la Venus.","Apropierea mare de centrul galaxiei.","Numărul mare de sateliți naturali."]','Întreabă-te ce „pătură” lipsește, astfel încât căldura să nu fie păstrată noaptea. Fără atmosferă, Mercur nu reține căldura, așa că se încinge puternic ziua și se răcește extrem noaptea.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f8f30cb7-5cba-488f-8a6c-9375cc9fea7c','9','geografie-fizica','published',1,35,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f8f30cb7-5cba-488f-8a6c-9375cc9fea7c','ro','Ce face din Terra o planetă unică în Sistemul Solar, conform lecției?','["Prezența inelelor și a multor sateliți.","Prezența apei în toate cele trei stări de agregare și a unei biosfere variate.","Lipsa totală a atmosferei.","Numărul foarte mare de cratere."]','Caută ceea ce există pe Terra și lipsește celorlalte planete. Doar Terra are apă în stare solidă, lichidă și gazoasă în același timp și o biosferă bogată, care susține viața.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('e520732b-95ab-4161-89d2-f0797ff84c6c','9','geografie-fizica','published',1,36,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('e520732b-95ab-4161-89d2-f0797ff84c6c','ro','Jupiter radiază de aproape două ori mai multă energie decât primește de la Soare. Ce putem deduce de aici?','["Că Jupiter este, de fapt, o stea.","Că are o sursă proprie de energie internă, nu doar lumina reflectată de la Soare.","Că se află foarte aproape de Soare.","Că nu primește deloc energie de la Soare."]','Dacă un corp dă mai multă energie decât primește, întreabă-te de unde vine surplusul. Jupiter degajă căldură din interiorul său, deci are o sursă internă proprie de energie, pe lângă cea primită de la Soare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5afb598f-3f79-495b-bf94-35d2e921e97d','9','geografie-fizica','published',0,37,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5afb598f-3f79-495b-bf94-35d2e921e97d','ro','Saturn are cea mai mică densitate dintre planete, mai mică chiar decât a apei. Ce înseamnă concret acest lucru?','["Că, teoretic, ar pluti pe apă, fiind alcătuit mai ales din gaze ușoare.","Că este cea mai grea planetă din sistem.","Că este alcătuit în întregime din metal.","Că nu are niciun inel."]','Compară densitatea planetei cu cea a apei și gândește-te ce plutește și ce se scufundă. Fiind mai puțin dens decât apa, Saturn ar pluti (teoretic) pe un ocean suficient de mare, pentru că e format mai ales din gaze ușoare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('26b883fa-9b2a-482a-bdf3-0d678d33f501','9','geografie-fizica','published',1,38,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('26b883fa-9b2a-482a-bdf3-0d678d33f501','ro','Uranus are axa de rotație înclinată aproape 98°, astfel încât se rotește „culcat”, aproape pe planul orbitei. Ce consecință are acest lucru?','["Se rotește mult mai repede decât celelalte planete.","Polii săi ajung pe rând orientați direct spre Soare, ducând la anotimpuri extreme.","Nu poate avea sateliți naturali.","Devine cea mai fierbinte planetă din sistem."]','Dacă planeta este „culcată”, gândește-te ce parte a ei ajunge îndreptată spre Soare în timpul orbitei. Cu axa aproape orizontală, polii lui Uranus sunt expuși pe rând spre Soare, ceea ce produce anotimpuri foarte lungi și extreme.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c3484c2c-d4b4-4f60-a3d2-7c81db1f4e7f','9','geografie-fizica','published',1,39,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c3484c2c-d4b4-4f60-a3d2-7c81db1f4e7f','ro','De pe Pământ vedem mereu aceeași față a Lunii. Care este explicația corectă?','["Pentru că Luna nu se rotește deloc în jurul axei sale.","Pentru că perioada ei de rotație este egală cu perioada de revoluție (27,32 zile).","Pentru că Luna este plată pe partea dinspre noi.","Pentru că Pământul stă nemișcat."]','Compară cele două perioade ale Lunii: cea de rotație și cea de revoluție. Fiindcă ele sunt egale, Luna se întoarce exact cu aceeași viteză cu care orbitează, așa că ne arată mereu aceeași față.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('1ed7a908-05b4-44bb-ba75-f637b7055640','9','geografie-fizica','published',1,40,1782766800000,1782766800000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('1ed7a908-05b4-44bb-ba75-f637b7055640','ro','Ce condiție trebuie îndeplinită pentru a se produce o eclipsă de Soare?','["Pământul să se afle între Soare și Lună.","Luna să se afle între Soare și Pământ, acoperind discul solar.","Soarele să se afle între Pământ și Lună.","Luna să intre complet în umbra Pământului."]','Gândește-te cine trebuie să stea la mijloc pentru a acoperi Soarele. La o eclipsă de Soare, Luna se interpune între Soare și Pământ și aruncă umbra ei pe suprafața Pământului.');
